// ─────────────────────────────────────────────────────────────
//  src/services/api.js
//  All calls to the NutriBite backend (Phase 2)
//  Falls back to Open Food Facts directly if backend is offline
// ─────────────────────────────────────────────────────────────

const BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// ── Token helpers ─────────────────────────────────────
export const getToken = () => localStorage.getItem('nb_token');
export const setToken = token => localStorage.setItem('nb_token', token);
export const clearToken = () => localStorage.removeItem('nb_token');

// ── Base fetch wrapper ────────────────────────────────
async function request(endpoint, options = {}) {
  const token = getToken();
  const headers = {
    'Content-Type': 'application/json',
    ...(token ? {
      Authorization: `Bearer ${token}`
    } : {}),
    ...options.headers
  };
  const res = await fetch(`${BASE}${endpoint}`, {
    ...options,
    headers
  });
  const data = await res.json();
  if (!res.ok) {
    throw new Error(data.message || `Request failed: ${res.status}`);
  }
  return data;
}

// ════════════════════════════════════════════════════════
//  AUTH
// ════════════════════════════════════════════════════════

export async function apiRegister({
  name,
  email,
  password,
  dietType,
  preferences
}) {
  const data = await request('/auth/register', {
    method: 'POST',
    body: JSON.stringify({
      name,
      email,
      password,
      dietType,
      preferences
    })
  });
  if (data.token) setToken(data.token);
  return data;
}
export async function apiLogin({
  email,
  password
}) {
  const data = await request('/auth/login', {
    method: 'POST',
    body: JSON.stringify({
      email,
      password
    })
  });
  if (data.token) setToken(data.token);
  return data;
}
export async function apiGetMe() {
  return request('/auth/me');
}
export async function apiUpdatePassword({
  currentPassword,
  newPassword
}) {
  return request('/auth/password', {
    method: 'PUT',
    body: JSON.stringify({
      currentPassword,
      newPassword
    })
  });
}
export function apiLogout() {
  clearToken();
}

